// Live values — the theme, plus the CSS the iframe generated for the readout.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  bg:         val('bg'),
  accent:     val('accent'),
  radius:     val('radius'),     // number → 'radiuspx' in the CSS
  hue:        val('hue'),
  css_export: nb.get('css_export'),  // the full stylesheet string, written back by the iframe
};
